// Local font stylesheets are generated by scripts/download-local-fonts.mjs.
// Keep font family names and CSS font-face definitions unchanged.
import { HERO_FONTS, getHeroFont } from "./hero-fonts";

const namesById = new Map(HERO_FONTS.map(({ id, name }) => [id, name]));
namesById.set("nanum-gothic", "Nanum Gothic");
const slug = (name) => name.toLowerCase().replace(/[^a-z0-9]/g, "");
const hrefFor = (id) => {
  const name = namesById.get(id);
  return name ? `/fonts/${slug(name)}/font.css` : null;
};
export function invitationFontStylesheets(config) {
  const ids = new Set();
  const hero = config?.hero;
  // Load the first visible intro font before the rest of the invitation fonts.
  if (hero?.intro?.enabled && hero.intro.text?.trim()) ids.add(getHeroFont(hero.intro.fontId).id);
  if (hero?.nameFontFamily && hero.nameFontFamily !== "inherit") ids.add(hero.nameFontFamily);
  for (const layer of hero?.textLayers || []) {
    if (layer.visible === false) continue;
    if (!(layer.source && layer.source !== "custom") && !layer.text?.trim()) continue;
    ids.add(getHeroFont(layer.fontId).id);
  }
  for (const role of ["heroTitle", "sectionTitle", "body", "caption"]) {
    const id = config?.typography?.[role]?.fontFamily;
    if (id) ids.add(id);
  }
  const button = config?.buttonStyle?.fontFamily;
  if (button) ids.add(button);
  return [...new Set([...ids].map(hrefFor).filter(Boolean))];
}
